// Publish the official logo supplied by the owner on 2026-10-15.
// Preserve the source's native 400px resolution. Do not redraw or upscale.
import { mkdirSync, writeFileSync } from "node:fs";

const LOGO_PNG_BASE64 =
  "";
mkdirSync("dist", { recursive: true });
writeFileSync("dist/logo.png", Buffer.from(LOGO_PNG_BASE64, "base64"));
writeFileSync(
  "dist/favicon.svg",
  `<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" viewBox="0 0 400 400"><image width="400" height="400" href="data:image/png;base64,${LOGO_PNG_BASE64}" xlink:href="data:image/png;base64,${LOGO_PNG_BASE64}"/></svg>`,
);
console.log("wrote official dist/logo.png and dist/favicon.svg");
